import json, datetime
ig = [
 ("Deosx1so2lJ","reel",1792327123,"9/16","Warum machen wir so viele Branchen?"),
 ("Dc78AUjI7Fm","p",1788677605,"4/5","Eine gute Website beginnt nicht mit Design.\nSie beginnt mit den richtigen Fragen.\n\nWas soll sie erreichen?\nWen soll sie überzeugen?\nUnd was muss passieren, damit aus einem Besucher ein Kunde wird?\n\nWir bauen keine Websites, damit Unternehmen „online gut aussehen“.\nWir bauen Werkzeuge, die für Unternehmen arbeiten."),
 ("Dc77-GioZwF","p",1788677584,"4/5","Strategie ist wichtig.\nAber irgendwann muss aus Gedanken etwas entstehen, das funktioniert.\n\nStruktur. Texte. Design. Technik. Nutzerführung.\nNicht als einzelne Bausteine – sondern als ein System mit einem klaren Ziel.\n\nEine Website sollte nicht einfach nur da sein.\nSie sollte etwas bewegen."),
 ("Dc7-W-DocE7","p",1788678833,"4/5",""),
 ("DeeMR-Xou-g","reel",1791974748,"9/16","Wo ist bei uns aktuell das Bottle Neck und wie wollen wir das lösen?"),
 ("DeWlhUeIYTi","reel",1791719396,"9/16","KI-Avatar für Kunden? Bringt das was?"),
 ("DeTsPRKIbid","reel",1791622157,"9/16","Du kannst alles? Musst du gar nicht – nur Spaß und Begeisterung für das, was du tust!"),
 ("DeOzqEBIePj","reel",1791458266,"9/16","Ja, richtig gehört: Briefe!"),
 ("DeEB7bfCHCx","p",1791096620,"4/5","Was macht bei einer Website eigentlich den Unterschied, bzw. was macht sie am Ende gut?"),
 ("DeB4YSbIzLI","reel",1791024687,"9/16","Wie baut eine Website eigentlich Vertrauen auf? 👀\n\nGanz einfach: Indem man zeigt, wer dahintersteht.\n\nEchte Gesichter. Das Team. Die Menschen, mit denen der Kunde später wirklich spricht. Einblicke ins Unternehmen, echte Projekte und eine klare Sprache statt austauschbarer Stockfotos und Marketing-Floskeln.\n\nGerade beim ersten Kontakt entscheidet die Website oft darüber, ob ein Unternehmen sympathisch und glaubwürdig wirkt – oder komplett anonym.\n\nUnser Ansatz bei der noll media GmbH deshalb: Menschen zeigen.\n\nDenn am Ende machen Menschen Geschäfte mit Menschen. 🤝\n\n#nollmedia #Webdesign #Website #Vertrauen #Unternehmen #Marketing"),
 ("Dd8vRAnoFnt","reel",1790851982,"9/16","WordPress ist unsicher? 👀 Nicht ganz.\n\nDas Problem ist meistens nicht WordPress selbst.\n\nDas Problem entsteht, wenn eine Website jahrelang läuft und sich niemand mehr wirklich darum kümmert.\n\nVeraltete Plugins, fehlende Updates, alte Themes oder Erweiterungen, die längst nicht mehr gepflegt werden – und plötzlich wird aus „Die Website läuft doch“ ein echtes Sicherheitsrisiko.\n\nEine Website ist eben kein Projekt, das nach dem Launch fertig ist.\n\nSie braucht Updates, Wartung und jemanden, der regelmäßig hinschaut. 🔐\n\nGenau deshalb denken wir bei der noll media GmbH Websites langfristig.\n\n#WordPress #Webdesign #Website #Webentwicklung #CyberSecurity #nollmedia"),
 ("DdyxfLco2Dz","reel",1790517640,"9/16","Wer sucht eigentlich auf Google? Und wenn ja, was?"),
 ("DdtzyQuooIx","p",1790351015,"4/5","Wer steckt eigentlich hinter noll media? 👋\n\nZeit für eine kleine Vorstellungsrunde.\n\nDen Anfang macht Christian – Geschäftsführer der noll media GmbH, Technik-Fan, Rennradfahrer und jemand, der ziemlich selten mit „Das haben wir schon immer so gemacht“ zufrieden ist. 😄\n\nNeue Ideen ausprobieren, bestehende Lösungen hinterfragen und Dinge immer ein Stück besser machen – genau das treibt ihn an.\n\nIm Unternehmen genauso wie auf dem Rennrad. 🚴‍♂️\n\nIn den nächsten Posts stellen wir euch noch mehr von den Menschen hinter der noll media GmbH vor.\n\n#nollmedia #Teamnollmedia #Webagentur #Webdesign #Digitalagentur #Montabaur"),
 ("DdoKraVoK97","reel",1790161718,"9/16","Unsere eigene Website war mal wieder fällig. 👀\n\nWir bauen jeden Tag Websites für andere Unternehmen – und jetzt haben wir uns endlich unsere eigene vorgenommen.\n\nNeues Design. Neue Inhalte. Neue Projekte. Und vor allem eine Website, die deutlich besser zeigt, was wir bei der noll media GmbH eigentlich machen.\n\nChristian gibt im Video schon mal einen kleinen Vorgeschmack. 🎥\n\nDie neue Website geht bald live.\n\nUnd ja… wir sind gespannt, was ihr dazu sagt. 👀\n\n#nollmedia #Webdesign #Website #Webentwicklung #Digitalagentur #Marketing"),
 ("DdjI3l1oTxJ","p",1789992967,"4/5","Organisation, Überblick und der Blick fürs Ganze. 🤝\n\nMelissa unterstützt bei noll media die Geschäftsführung und sorgt dafür, dass im Hintergrund viele Dinge zusammenlaufen.\n\nVon organisatorischen und internen Themen bis hin zur Abstimmung im Tagesgeschäft hält sie Christian den Rücken frei, bringt ihre eigene Sichtweise ein und behält dabei immer zwei Dinge im Blick: zufriedene Kunden und ein starkes Team.\n\nGerade diese Mischung aus Organisation, Austausch und Verantwortung macht ihre Arbeit für sie besonders spannend.\n\nDenn oft sind es genau die Dinge im Hintergrund, die dafür sorgen, dass vorne alles rund läuft. ✨\n\n#nollmedia #teamnollmedia #agenturleben #organisation #teamwork #assistenz"),
 ("DdbG2jJors3","p",1789723477,"4/5","Organisation, Marketing und jeden Tag neue Herausforderungen. 🚀\n\nSophia ist bei noll media für Operations verantwortlich und sorgt dafür, dass im Hintergrund alles zusammenläuft.\n\nSchon früh war für sie klar, dass ihr Weg ins Marketing führen soll. Über Ausbildung, Berufserfahrung und Studium wurde aus diesem Wunsch schließlich genau der Job, den sie heute macht.\n\nSeit über fünf Jahren ist sie Teil von noll media – und genau die Abwechslung macht für sie den Unterschied: neue Trends, neue Systeme, unterschiedliche Kunden und immer wieder neue Aufgaben.\n\nDenn Stillstand passt weder zum Marketing noch zu uns. 💡"),
 ("DdWUt9VIRGW","p",1789562971,"4/5","Aus Ideen werden digitale Erlebnisse. 💻✨\n\nAndre ist bei noll media im Bereich Webdesign zuhause und sorgt dafür, dass aus ersten Vorstellungen moderne Websites entstehen, die nicht nur gut aussehen, sondern Unternehmen auch wirklich weiterbringen.\n\nBesonders spannend für ihn: bestehende Websites neu zu denken, Designs auf ein neues Level zu bringen und mit Animationen, Effekten und klaren Strukturen einen Auftritt zu schaffen, der im Kopf bleibt.\n\nDenn gutes Webdesign ist mehr als Optik.\nEs verbindet Marke, Nutzererlebnis und Funktion."),
 ("DdTSLjmIVK1","p",1789460990,"4/5","Hinter jeder starken Website steckt Technik, die einfach funktionieren muss. ⚙️\n\nSteven sorgt bei noll media dafür, dass im Hintergrund alles sauber läuft – von Websites und Hosting über Tracking bis hin zu Automatisierungen.\n\nSein Anspruch: Probleme nicht nur schnell lösen, sondern Strukturen schaffen, die langfristig funktionieren.\n\nMit klaren Standards, smarten Prozessen und den richtigen KI-Tools sorgt er dafür, dass unsere Technik stabil bleibt und wir jeden Tag ein Stück effizienter arbeiten.\n\nKurz gesagt: Gute Technik fällt nicht auf. Man merkt nur, wenn sie fehlt. 👀"),
 ("DdEsSWzonEW","reel",1788971676,"9/16","Hi, ich bin Christian. Und ich nehme euch ab jetzt mit hinter die Kulissen von noll media.\n\nWas mich antreibt? Technik, die den Alltag leichter macht. Websites, die einem Unternehmen wirklich gerecht werden. Und Lösungen, die unseren Kunden Arbeit abnehmen.\n\nHier bekommt ihr Einblicke in unseren Agenturalltag: Welche Entscheidungen treffen wir? Für wen arbeiten wir? Was setzen wir um – und funktioniert es am Ende auch?\n\nIm neuen YouTube-Video erzähle ich euch, wie alles angefangen hat und was wir mit diesem Kanal vorhaben."),
]
iso=lambda ts: datetime.datetime.utcfromtimestamp(ts).strftime('%Y-%m-%dT%H:%M:%SZ')
items=[]
for sc,kind,ts,ratio,cap in ig:
    # Medien: images/social/ig-<shortcode>.jpg (Cover in Originalformat)
    it={"id":"ig-"+sc,"network":"instagram","type":"video" if kind=="reel" else "image",
        "url":f"https://www.instagram.com/{kind}/{sc}/","image":f"images/social/ig-{sc}.jpg",
        "video":None,"ratio":ratio,"date":iso(ts),"text":cap}
    if sc in ("Deosx1so2lJ","DeB4YSbIzLI","DdEsSWzonEW"): it["ratio"]="9/16"
    items.append(it)
items += [
 {"id":"yt-SOLQWVXB1jc","network":"youtube","type":"youtube","youtubeId":"SOLQWVXB1jc","url":"https://www.youtube.com/watch?v=SOLQWVXB1jc","image":"images/social/yt-SOLQWVXB1jc.jpg","ratio":"16/9","date":"2026-09-23T18:07:10Z","title":"4 Kunden. 4 Websites. So arbeiten wir wirklich.","text":"Was steckt hinter einer guten Unternehmenswebsite? Ich zeige es euch an vier echten Kundenprojekten von noll media. 👀\n\nVom Beschwerdefinder einer Orthopädiepraxis über komplexe Industrieprodukte bis zum Hauskonfigurator: Jede Website muss andere Fragen beantworten.\n\nIhr erfahrt auch, warum wir nach neun Jahren WordPress auf Astro und Payload CMS setzen und welche Rolle KI inzwischen bei unserer Entwicklung spielt."},
 {"id":"yt-IRkirgQRDfc","network":"youtube","type":"youtube","youtubeId":"IRkirgQRDfc","url":"https://www.youtube.com/watch?v=IRkirgQRDfc","image":"images/social/yt-IRkirgQRDfc.jpg","ratio":"16/9","date":"2026-09-09T17:24:16Z","title":"Das bin ich, Christian Noll – Welcome to YouTube","text":"Hi, ich bin Christian, Inhaber von noll media aus Montabaur.\n\nWir entwickeln digitale Lösungen, die Unternehmen weiterbringen: Websites, Online-Shops, Performance-Marketing und Automatisierungen.\n\nIn diesem Video erfahrt ihr, warum ich die Agentur gegründet habe, was mich an Technik begeistert und warum wir euch ab jetzt in unseren Alltag mitnehmen.\n\n#nollmedia #Webdesign #Agenturalltag"},
]
with open("data/social-wall.json","w") as f: json.dump({"items":items,"linkedin":[]},f,ensure_ascii=False,indent=2)
with open("js/social-wall-data.js","w") as f:
    f.write("/* Statischer Stand der Social Wall (Fallback, wenn api/social-wall.php\n   nicht erreichbar ist – z. B. lokal per file://). Gleiche Struktur wie\n   data/social-wall.json. Neu erzeugen: siehe SOCIAL-WALL.md. */\n")
    f.write("window.NOLL_SOCIAL_WALL = "+json.dumps({"items":items},ensure_ascii=False,indent=2)+";\n")
print(len(items))
